                        "type": 4,
                        "title": "<p style=\"text-align: justify;\">However, this bustling tulip market eventually reached its breaking point. As with many speculative bubbles, the tulip craze was unsustainable, and prices eventually began to plummet. Once people realized that tulip prices had risen far beyond reasonable levels, panic selling ensued, and the market collapsed. The dramatic fall in prices left many investors in financial ruin, as the value of tulips dwindled to a fraction of their peak. The tulip mania became one of history&rsquo;s most famous economic bubbles, offering a cautionary tale about the dangers of speculation and the risks inherent in market bubbles.<\/p>",
