      '<p><strong>Four people respond in the comments section of an online newspaper about their last holiday. Read their comments and answer the questions below. </strong></p>\r\n\r\n<p><strong>Ali </strong></p>\r\n\r\n<p><strong>I went to this island to visit some remote beaches. I thought walking shoes would be helpful. However, when I arrived, I realized that I had forgotten to bring them. The remoteness means there are no other visitors. It is good, but it has its downside. There is nowhere to buy food and drink, so I have to bring my own. </strong></p>\r\n\r\n<p><strong>Bruno </strong></p>\r\n\r\n<p><strong>Being an architect, when I go abroad, I am very curious about the construction of local buildings.&nbsp;I often lay down at the beach and buy some souvenirs at the local shop. This time, I traveled by taxi to go around. There is no one to share so the cost is high. However, it&rsquo;s worth it because I could see some beautiful traditional houses. </strong></p>\r\n\r\n<p><strong>Carla </strong></p>\r\n\r\n<p><strong>The sharp bends of the island look dangerous and that put me off hiring a car, especially when it is costly.&nbsp;Therefore, I chose to travel by bus. However, the bus service is not very frequent. If they improve it, it would be perfect. I visit some famous places near my hotel on foot. I love it because I can see many beautiful locations. </strong></p>\r\n\r\n<p><strong>Deniz </strong></p>\r\n\r\n<p><strong>I stayed in a village and ate at various local restaurants.&nbsp;I cannot recommend a specific dish because everything was amazing. However, if you want to cook by yourself, you would need to take a bus to the town. There is a street market where you can buy some local products. I had some real bargains there.</strong></p>',
