    title:
      '<p><strong>Four people express their opinions about the new station. Read their comments and answer the questions below. </strong></p>\r\n\r\n<p><strong>Person A: </strong></p>\r\n\r\n<p><strong>Originally, the city planners promised money for building a hospital initially. I don&#39;t understand why they switched to construct a new station then. This new station won&#39;t solve the traffic jams, and it will require the city&#39;s budget every year. Therefore, we won&#39;t have money left to build a hospital while health should be a priority, I believe it&#39;s better to invest in health services instead. </strong></p>\r\n\r\n<p><strong>Person B: </strong></p>\r\n\r\n<p><strong>The new station will be in the residential area, close to the hospital and university. We already have buses for getting around, and even though they might be slow sometimes, that&#39;s not a reason for being late. I always go to work on time, and I think everyone should work on their personal schedule. People often blame traffic for being late, but I manage to avoid that. </strong></p>\r\n\r\n<p><strong>Person C: </strong></p>\r\n\r\n<p><strong>I take the train to work every day, and I am tired of the overcrowded trains. I believe investing in a new station is worthwhile, as it could enhance the transportation system and alleviate congestion at the current station. We should consider placing the new station in densely populated residential areas, as this would improve train travel and help reduce crowding. </strong></p>\r\n\r\n<p><strong>Person D: </strong></p>\r\n\r\n<p><strong>The city planners say that investing in a new station may not be necessary. Both the current station and the bus services appear to work well. Although I don&#39;t use trains regularly, I have found the service to be satisfactory whenever I do. The existing facilities are adequate, and I don&#39;t see a pressing need to spend money on a new station at this time.</strong></p>',
